ventas = xl("Ventas[#All]", headers=True)
resumen = ventas.groupby("Categoria", as_index=False)["Importe"].sum()
resumen = resumen.sort_values("Importe", ascending=False)

ax = resumen.plot(
    kind="bar",
    x="Categoria",
    y="Importe",
    legend=False,
    title="Ventas por categoría"
)
ax.set_ylabel("Importe")
ax
